import { componentAttrs } from "../_utils/component.helper";

const ASSET_LISTING_BASE_URL =
  "https://nt.gov.au/web-design-system/listings/asset-children-json-feed";
const ROOT_ID_PARAM_NAME = "rootId";

function parseAssetUriParts(uri) {
  const match = /^matrix-asset:\/\/([a-zA-Z0-9.-]+)\/(\d+)(?::.+)?$/.exec(
    String(uri ?? ""),
  );
  return match ? { domain: match[1], id: match[2] } : null;
}

function settleResult(settled) {
  if (settled.status === "fulfilled") {
    return { ok: true, data: settled.value };
  }
  const reason = settled.reason;
  return { ok: false, error: reason?.message ?? String(reason) };
}

/**
 * Fetches a Squiz Matrix Asset Listing configured as a JSON feed, with the
 * parent asset's ID passed as a Dynamic Parameter (Replacement Root Node)
 * via the query string -- confirmed working against both a folder and a
 * page_content parent, returning real children with id/name/url/metadata.
 * Plain unauthenticated fetch(), no token needed.
 */
async function fetchAssetListingChildren(assetId) {
  if (!assetId) {
    return {
      skipped: true,
      reason: "No parentAsset selected, or its URI didn't parse into an asset ID.",
    };
  }

  const url = `${ASSET_LISTING_BASE_URL}?${ROOT_ID_PARAM_NAME}=${encodeURIComponent(assetId)}`;

  try {
    const res = await fetch(url);
    const text = await res.text();
    let body;
    try {
      body = JSON.parse(text);
    } catch {
      body = text.slice(0, 2000);
    }
    return { call: `GET ${url}`, status: res.status, ok: res.ok, body };
  } catch (err) {
    return { call: `GET ${url}`, ok: false, error: err?.message ?? String(err) };
  }
}

export default {
  async main(input = {}, info) {
    const { parentAsset = "" } = input;
    const { fns } = info;
    const parts = parentAsset ? parseAssetUriParts(parentAsset) : null;

    const resolveUriPromise = parentAsset
      ? fns.resolveUri(parentAsset)
      : Promise.resolve({ skipped: true, reason: "No parentAsset selected." });

    const [resolveUriResult, childrenResult] = await Promise.allSettled([
      resolveUriPromise,
      fetchAssetListingChildren(parts ? parts.id : null),
    ]);

    const display = {
      parentAsset: parentAsset || "(none)",
      parentAssetResolved: settleResult(resolveUriResult),
      children: settleResult(childrenResult),
    };

    return /*html*/ `<div ${componentAttrs("asset-children-picker", input)}>
      <details open>
        <summary>Asset Children Picker</summary>
        <pre><code>${JSON.stringify(display, null, 2)}</code></pre>
      </details>
    </div>`;
  },
};
